import React, { useState, useEffect } from "react";
import { BrowserRouter as Router, Route, Routes, Link, Navigate } from "react-router-dom";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import { z } from "zod";
import "./styles.css";

// Notification Component
const Notification = ({ message, onClose }) => {
  useEffect(() => {
    const timer = setTimeout(() => {
      onClose();
    }, 2000);
    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div className="notification">
      {message}
    </div>
  );
};

// OTP Form Schema
const FormSchema = z.object({
  pin: z.string().min(6, {
    message: "Your one-time password must be 6 characters.",
  }),
});

// OTP Form Component
function InputOTPForm({ onVerify }) {
  const form = useForm({
    resolver: zodResolver(FormSchema),
    defaultValues: {
      pin: "",
    },
  });

  const onSubmit = (data) => {
    console.log("OTP Verified:", data.pin);
    onVerify();
  };

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="w-2/3 space-y-6">
        <FormField
          control={form.control}
          name="pin"
          render={({ field }) => (
            <FormItem>
              <FormLabel>One-Time Password</FormLabel>
              <FormControl>
                <InputOTP maxLength={6} {...field}>
                  <InputOTPGroup>
                    <InputOTPSlot index={0} />
                    <InputOTPSlot index={1} />
                    <InputOTPSlot index={2} />
                    <InputOTPSlot index={3} />
                    <InputOTPSlot index={4} />
                    <InputOTPSlot index={5} />
                  </InputOTPGroup>
                </InputOTP>
              </FormControl>
              <FormDescription>
                Please enter the one-time password sent to your email/phone.
              </FormDescription>
              <FormMessage />
            </FormItem>
          )}
        />
        <Button type="submit">Verify OTP</Button>
      </form>
    </Form>
  );
}

// Home Page Component
const HomePage = () => {
  return (
    <div className="homePage">
      <h1 className="heading">Welcome to Binance Clone</h1>
      <Link to="/login">
        <button className="button">Get Started</button>
      </Link>
      <p className="linkText">
        <Link to="/admin-login" className="link">
          Admin Login
        </Link>
      </p>
    </div>
  );
};

// Login Page Component
const LoginPage = ({ onLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);

  const handleLogin = () => {
    if (!username || !password) {
      setError("Please fill in all fields.");
      return;
    }

    // Simulate OTP sending (frontend-only)
    setOtpSent(true);
    setError("");
  };

  const handleOTPVerification = () => {
    if (!otpVerified) {
      setError("Please verify OTP first.");
      return;
    }

    onLogin();
  };

  return (
    <div className="loginPage">
      <h2 className="heading">Login</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="text"
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      {!otpSent ? (
        <button onClick={handleLogin} className="button">
          Login
        </button>
      ) : (
        <>
          <InputOTPForm onVerify={() => setOtpVerified(true)} />
          <button onClick={handleOTPVerification} className="button">
            Verify OTP
          </button>
        </>
      )}
      <p className="linkText">
        <Link to="/forgot-password" className="link">
          Forgot Password?
        </Link>
      </p>
      <p className="linkText">
        Don't have an account?{" "}
        <Link to="/signup" className="link">
          Sign Up
        </Link>
      </p>
    </div>
  );
};

// Signup Page Component
const SignupPage = ({ onSignup }) => {
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [phone, setPhone] = useState("");
  const [error, setError] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);

  const handleSendOTP = () => {
    if (!email || !password || !phone) {
      setError("Please fill in all fields.");
      return;
    }

    const phoneRegex = /^\+92\d{9}$/;
    if (!phoneRegex.test(phone)) {
      setError("Invalid phone number. Please use the format +92XXXXXXXXX.");
      return;
    }

    // Simulate OTP sending (frontend-only)
    setOtpSent(true);
    setError("");
  };

  const handleSignup = () => {
    if (!otpVerified) {
      setError("Please verify OTP first.");
      return;
    }

    onSignup({ email, password, phone });
  };

  return (
    <div className="signupPage">
      <h2 className="heading">Sign Up</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="email"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password (min 8 characters)"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number (+92XXXXXXXXX)"
        value={phone}
        onChange={(e) => setPhone(e.target.value)}
        className="input"
      />
      {!otpSent ? (
        <button onClick={handleSendOTP} className="button">
          Send OTP
        </button>
      ) : (
        <>
          <InputOTPForm onVerify={() => setOtpVerified(true)} />
          <button onClick={handleSignup} className="button">
            Sign Up
          </button>
        </>
      )}
      <p className="linkText">
        Already have an account?{" "}
        <Link to="/login" className="link">
          Login
        </Link>
      </p>
    </div>
  );
};

// Forgot Password Page Component
const ForgotPasswordPage = () => {
  const [email, setEmail] = useState("");
  const [error, setError] = useState("");
  const [success, setSuccess] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [otpVerified, setOtpVerified] = useState(false);

  const handleSendOTP = () => {
    if (!email) {
      setError("Please enter your email.");
      return;
    }

    // Simulate OTP sending (frontend-only)
    setOtpSent(true);
    setError("");
  };

  const handleResetPassword = () => {
    if (!otpVerified) {
      setError("Please verify OTP first.");
      return;
    }

    setSuccess("Password reset successful!");
  };

  return (
    <div className="forgotPasswordPage">
      <h2 className="heading">Trouble logging in?</h2>
      <p>Enter your email, and we'll send you a link to get back into your account.</p>
      {error && <div className="error">{error}</div>}
      {success && <div className="success">{success}</div>}
      <input
        type="text"
        placeholder="Email"
        value={email}
        onChange={(e) => setEmail(e.target.value)}
        className="input"
      />
      {!otpSent ? (
        <button onClick={handleSendOTP} className="button">
          Send OTP
        </button>
      ) : (
        <>
          <InputOTPForm onVerify={() => setOtpVerified(true)} />
          <button onClick={handleResetPassword} className="button">
            Reset Password
          </button>
        </>
      )}
      <p className="linkText">
        <Link to="/login" className="link">
          Back to Login
        </Link>
      </p>
    </div>
  );
};

// KYC Form Component
const KYCForm = ({ onKYCSubmit }) => {
  const [name, setName] = useState("");
  const [phoneNumber, setPhoneNumber] = useState("");
  const [documentType, setDocumentType] = useState("passport");
  const [picture, setPicture] = useState(null);
  const [error, setError] = useState("");

  const handleSubmit = () => {
    if (!name || !phoneNumber || !documentType || !picture) {
      setError("Please fill in all fields.");
      return;
    }
    console.log("Submitting KYC with:", {
      name,
      phoneNumber,
      documentType,
      picture,
    });
    onKYCSubmit();
  };

  return (
    <div className="kycPage">
      <h2 className="heading">KYC Verification</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="text"
        placeholder="Full Name"
        value={name}
        onChange={(e) => setName(e.target.value)}
        className="input"
      />
      <input
        type="text"
        placeholder="Phone Number"
        value={phoneNumber}
        onChange={(e) => setPhoneNumber(e.target.value)}
        className="input"
      />
      <select
        value={documentType}
        onChange={(e) => setDocumentType(e.target.value)}
        className="input"
      >
        <option value="passport">Passport</option>
        <option value="driver_license">Driver's License</option>
        <option value="ID_card">ID Card</option>
        <option value="picture">Picture</option>
      </select>
      <input
        type="file"
        onChange={(e) => setPicture(e.target.files[0])}
        className="input"
      />
      <button onClick={handleSubmit} className="button">
        Submit
      </button>
    </div>
  );
};

// Admin Panel Component
const AdminPanel = ({ kycRequests, onApprove, onReject }) => {
  return (
    <div className="adminPanel">
      <h2 className="heading">Admin Panel - KYC Requests</h2>
      <table>
        <thead>
          <tr>
            <th>Name</th>
            <th>Phone Number</th>
            <th>Document Type</th>
            <th>Status</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {kycRequests.map((request, index) => (
            <tr key={index}>
              <td>{request.name}</td>
              <td>{request.phoneNumber}</td>
              <td>{request.documentType}</td>
              <td>{request.status}</td>
              <td>
                <button onClick={() => onApprove(index)} className="button">
                  Approve
                </button>
                <button onClick={() => onReject(index)} className="button">
                  Reject
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

// AdminLogin Component
const AdminLogin = ({ onAdminLogin }) => {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  const handleLogin = () => {
    if (username === "admin" && password === "admin123") {
      onAdminLogin();
    } else {
      setError("Invalid credentials.");
    }
  };

  return (
    <div className="adminLogin">
      <h2 className="heading">Admin Login</h2>
      {error && <div className="error">{error}</div>}
      <input
        type="text"
        placeholder="Username"
        value={username}
        onChange={(e) => setUsername(e.target.value)}
        className="input"
      />
      <input
        type="password"
        placeholder="Password"
        value={password}
        onChange={(e) => setPassword(e.target.value)}
        className="input"
      />
      <button onClick={handleLogin} className="button">
        Login
      </button>
      <p className="linkText">
        <Link to="/" className="link">
          Back to Home
        </Link>
      </p>
    </div>
  );
};

// Dashboard Component
const Dashboard = ({ user, kycStatus, accountStatus }) => {
  const [activeTab, setActiveTab] = useState("transfer");
  const [walletId, setWalletId] = useState("");
  const [receiverWalletId, setReceiverWalletId] = useState("");
  const [amount, setAmount] = useState("");
  const [totalCoins, setTotalCoins] = useState(1000);
  const [notification, setNotification] = useState("");
  const [transactionHistory, setTransactionHistory] = useState([]);
  const [conversionType, setConversionType] = useState("coinToUsd");
  const [conversionAmount, setConversionAmount] = useState("");
  const [conversionResult, setConversionResult] = useState("");

  const handleTransfer = () => {
    if (!walletId || !receiverWalletId || !amount) {
      setNotification("Please fill all fields.");
      return;
    }

    if (parseInt(amount) > totalCoins) {
      setNotification("Insufficient coins.");
      return;
    }

    const newTransaction = {
      id: transactionHistory.length + 1,
      from: walletId,
      to: receiverWalletId,
      amount: parseInt(amount),
      date: new Date().toLocaleString(),
      type: "Transfer",
      status: "Completed",
    };

    setTransactionHistory([...transactionHistory, newTransaction]);
    setTotalCoins(totalCoins - parseInt(amount));
    setNotification("Transfer successful!");
    setWalletId("");
    setReceiverWalletId("");
    setAmount("");
  };

  const handleConversion = () => {
    if (!conversionAmount) {
      setNotification("Please enter an amount.");
      return;
    }

    const rate = 2000;
    if (conversionType === "coinToUsd") {
      setConversionResult(`$${(conversionAmount * rate).toFixed(2)}`);
    } else {
      setConversionResult(`${(conversionAmount / rate).toFixed(6)} ETH`);
    }
  };

  return (
    <div className="dashboard">
      <h2 className="heading">Dashboard</h2>
      {accountStatus === "blocked" && (
        <div className="blockedBanner">
          Your account is blocked. Contact support.
        </div>
      )}
      {notification && (
        <Notification
          message={notification}
          onClose={() => setNotification("")}
        />
      )}
      <div className="tabs">
        <button
          onClick={() => setActiveTab("transfer")}
          className={activeTab === "transfer" ? "activeTab" : "tab"}
        >
          Transfer Coins
        </button>
        <button
          onClick={() => setActiveTab("total")}
          className={activeTab === "total" ? "activeTab" : "tab"}
        >
          Total Coins
        </button>
        <button
          onClick={() => setActiveTab("history")}
          className={activeTab === "history" ? "activeTab" : "tab"}
        >
          Transaction History
        </button>
        <button
          onClick={() => setActiveTab("conversion")}
          className={activeTab === "conversion" ? "activeTab" : "tab"}
        >
          Coin Conversion
        </button>
      </div>

      {activeTab === "transfer" && (
        <div className="transferTab">
          <h3>Transfer Coins</h3>
          <input
            type="text"
            placeholder="Your Wallet ID"
            value={walletId}
            onChange={(e) => setWalletId(e.target.value)}
            className="input"
          />
          <input
            type="text"
            placeholder="Receiver Wallet ID"
            value={receiverWalletId}
            onChange={(e) => setReceiverWalletId(e.target.value)}
            className="input"
          />
          <input
            type="number"
            placeholder="Amount"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            className="input"
          />
          <button onClick={handleTransfer} className="button">
            Transfer
          </button>
        </div>
      )}

      {activeTab === "total" && (
        <div className="totalTab">
          <h3>Total Coins</h3>
          <p>You have {totalCoins} coins.</p>
        </div>
      )}

      {activeTab === "history" && (
        <div className="historyTab">
          <h3>Transaction History</h3>
          {transactionHistory.length === 0 ? (
            <p>No transactions yet.</p>
          ) : (
            <table>
              <thead>
                <tr>
                  <th>Date/Time</th>
                  <th>Type</th>
                  <th>Amount</th>
                  <th>Target Wallet</th>
                  <th>Status</th>
                </tr>
              </thead>
              <tbody>
                {transactionHistory.map((transaction) => (
                  <tr key={transaction.id}>
                    <td>{transaction.date}</td>
                    <td>{transaction.type}</td>
                    <td>{transaction.amount}</td>
                    <td>{transaction.to}</td>
                    <td>{transaction.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      )}

      {activeTab === "conversion" && (
        <div className="conversionTab">
          <h3>Coin Conversion</h3>
          <p>Total Coins: {totalCoins}</p>
          <select
            value={conversionType}
            onChange={(e) => setConversionType(e.target.value)}
            className="input"
          >
            <option value="coinToUsd">Coin to USD</option>
            <option value="usdToCoin">USD to Coin</option>
          </select>
          <input
            type="number"
            placeholder="Amount"
            value={conversionAmount}
            onChange={(e) => setConversionAmount(e.target.value)}
            className="input"
          />
          <button onClick={handleConversion} className="button">
            Convert
          </button>
          {conversionResult && <p>Result: {conversionResult}</p>}
        </div>
      )}

      <div className="kycStatus">
        <h3>KYC Status</h3>
        <p>{kycStatus}</p>
      </div>
    </div>
  );
};

// App Component
const App = () => {
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isAdminLoggedIn, setIsAdminLoggedIn] = useState(false);
  const [isKYCSubmitted, setIsKYCSubmitted] = useState(false);
  const [user, setUser] = useState(null);
  const [kycRequests, setKycRequests] = useState([]);
  const [kycStatus, setKycStatus] = useState("Pending");
  const [accountStatus, setAccountStatus] = useState("active");

  const handleLogin = () => {
    setIsLoggedIn(true);
  };

  const handleAdminLogin = () => {
    setIsAdminLoggedIn(true);
  };

  const handleSignup = (userData) => {
    console.log("User signed up:", userData);
    setUser(userData);
    setIsLoggedIn(true);
  };

  const handleKYCSubmit = (kycData) => {
    setKycRequests([...kycRequests, { ...kycData, status: "Pending" }]);
    setIsKYCSubmitted(true);
  };

  const handleApprove = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Approved";
    setKycRequests(updatedRequests);
    setKycStatus("Approved");
  };

  const handleReject = (index) => {
    const updatedRequests = [...kycRequests];
    updatedRequests[index].status = "Rejected";
    setKycRequests(updatedRequests);
    setKycStatus("Rejected");
  };

  return (
    <Router>
      <div className="app">
        <Routes>
          <Route path="/" element={<HomePage />} />
          <Route
            path="/login"
            element={
              isLoggedIn ? (
                <Navigate to="/kyc" />
              ) : (
                <LoginPage onLogin={handleLogin} />
              )
            }
          />
          <Route
            path="/admin-login"
            element={
              isAdminLoggedIn ? (
                <Navigate to="/admin" />
              ) : (
                <AdminLogin onAdminLogin={handleAdminLogin} />
              )
            }
          />
          <Route
            path="/forgot-password"
            element={<ForgotPasswordPage />}
          />
          <Route
            path="/signup"
            element={<SignupPage onSignup={handleSignup} />}
          />
          <Route
            path="/kyc"
            element={
              isKYCSubmitted ? (
                <Navigate to="/dashboard" />
              ) : isLoggedIn ? (
                <KYCForm onKYCSubmit={handleKYCSubmit} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/dashboard"
            element={
              isKYCSubmitted ? (
                <Dashboard user={user} kycStatus={kycStatus} accountStatus={accountStatus} />
              ) : (
                <Navigate to="/login" />
              )
            }
          />
          <Route
            path="/admin"
            element={
              isAdminLoggedIn ? (
                <AdminPanel
                  kycRequests={kycRequests}
                  onApprove={handleApprove}
                  onReject={handleReject}
                />
              ) : (
                <Navigate to="/admin-login" />
              )
            }
          />
        </Routes>
      </div>
    </Router>
  );
};

export default App;
